#include <omp.h>
#include <vector>
#include <array>

/* Vector x contains values between 0 and 100, inclusive. Count the number of
   values in [0,10), [10, 20), [20, 30), ... and store the counts in `bins`.
   Use OpenMP to compute in parallel.
   Example:

   input: [7, 32, 95, 12, 39, 32, 11, 71, 70, 66]
   output: [1, 2, 0, 3, 0, 0, 1, 2, 0, 1]
*/
void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    // Initialize bins to zero
    for (int i = 0; i < 10; ++i) {
        bins[i] = 0;
    }

    // Use a private array for each thread to avoid race conditions
    #pragma omp parallel
    {
        std::array<size_t, 10> local_bins;
        for (int i = 0; i < 10; ++i) {
            local_bins[i] = 0;
        }

        #pragma omp for
        for (size_t i = 0; i < x.size(); ++i) {
            int bin_index = static_cast<int>(x[i] / 10.0);
            // Clamp to [0, 9] since values are in [0, 100]
            // Note: value 100 would give bin_index 10, but the problem says values are in [0,100] inclusive
            // and bins are [0,10), [10,20), ..., [90,100). So 100 should go into bin 9? 
            // Actually, [90,100) doesn't include 100. Let's re-read: "values between 0 and 100, inclusive"
            // and bins are [0,10), [10,20), ..., [90,100). So 100 is not in any bin? 
            // But the example doesn't have 100. Let's assume values are in [0,100) effectively, or that 100 maps to bin 9.
            // To be safe, clamp bin_index to [0, 9].
            if (bin_index < 0) bin_index = 0;
            if (bin_index > 9) bin_index = 9;
            local_bins[bin_index]++;
        }

        // Reduce local_bins into global bins
        #pragma omp critical
        {
            for (int i = 0; i < 10; ++i) {
                bins[i] += local_bins[i];
            }
        }
    }
}
